-- Admin units (34 tỉnh + ~3321 xã) + migrate posts/place_aliases sang admin_unit_id
-- Nguồn seed: sapnhap.bando.com.vn (CC-BY-NC) via HF sapnhap-bando-vn

create table if not exists public.admin_units (
  id uuid primary key,
  code text not null unique,
  name text not null,
  level text not null check (level in ('province', 'commune')),
  kind text,
  parent_id uuid references public.admin_units(id),
  zone text check (zone is null or zone in ('bac', 'trung', 'nam')),
  merged_from text,
  lat double precision,
  lng double precision,
  sort_order int not null default 0,
  check (
    (level = 'province' and parent_id is null)
    or (level = 'commune' and parent_id is not null)
  )
);

create index if not exists admin_units_parent_idx on public.admin_units (parent_id);
create index if not exists admin_units_level_idx on public.admin_units (level);

alter table public.admin_units enable row level security;
drop policy if exists admin_units_read on public.admin_units;
create policy admin_units_read on public.admin_units for select to authenticated using (true);

-- Seed provinces
on conflict (code) do update set name=excluded.name, kind=excluded.kind, zone=excluded.zone, merged_from=excluded.merged_from, lat=excluded.lat, lng=excluded.lng, sort_order=excluded.sort_order;

-- Seed communes
on conflict (code) do update set name=excluded.name, kind=excluded.kind, parent_id=excluded.parent_id, merged_from=excluded.merged_from, lat=excluded.lat, lng=excluded.lng;

